def drive(me, enemy, arena):
    # Aggressive pursuit: point at enemy and go fast
    bearing = bearing_to(enemy.x, enemy.y)          # degrees, -180..180
    # Turn proportionally, but limit turn rate
    turn = max(-1.0, min(1.0, bearing / 30.0))      # 30° -> full differential
    # Forward throttle high when roughly aimed
    if abs(bearing) < 45.0:
        throttle = 1.0
    else:
        throttle = 0.6
    left = throttle + turn
    right = throttle - turn
    # Clamp to [-1,1]
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)

